pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ownerCaller, address _owner) public {
        // Keep the fuzzed domain wide: ownerCaller can be anything
        vm.assume(ownerCaller != address(0));
        // Deploy with the fuzzed ownerCaller as the initial owner
        vm.prank(ownerCaller);
        c = new C();
        // The initial owner calls setOwner with the fuzzed _owner
        vm.prank(ownerCaller);
        bool ok;
        try c.setOwner(_owner) returns (bool success) { ok = success; } catch { ok = false; }
        // If the call succeeded (i.e. caller is owner), the stored owner must be _owner.
        // If the call failed (non-owner), the stored owner must remain ownerCaller.
        if (ok) {
            assertTrue(c.owner() == _owner);
        } else {
            assertTrue(c.owner() == ownerCaller);
        }
    }
}

