pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        // Ensure _owner is not the zero address to keep test clean
        vm.assume(_owner != address(0));
        vm.assume(_owner != address(this));
        // The caller must be the current owner for onlyOwner to pass.
        address currentOwner = c.owner();
        vm.prank(currentOwner);
        (bool callSuccess, bytes memory retData) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, _owner));
        // The call must not revert in either version
        assertTrue(callSuccess, "call reverted");
        // Decode the returned bool
        bool returnedSuccess = abi.decode(retData, (bool));
        // The reference contract always returns true on success; the mutant returns false
        assertTrue(returnedSuccess, "setOwner must return true on success");
    }
}

